-- The Shattered Halls: spawns that TrinityCore 3.3.5 (sniffed build 14545) and AzerothCore (sniffed build
-- 46924) both have within 2.5 yards and that SkyFire lacked (nothing of SkyFire within 3 yards):
-- Fel Orc Converts, Shattered Hand Archers, Zealots, Champion and Assassins, Creeping Oozes and
-- Oozelings, Hellfire Death Braziers and Training Dummies. Triggers, critters, Savages (SmartAI with
-- phases not ported) and the executioner event creatures are left out.
DELETE FROM `creature` WHERE `guid` BETWEEN 8319100 AND 8319135;

-- Creeping Oozeling casts Sticky Ooze like the Creeping Ooze does (SkyFire only had the latter).
UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE `entry` = 17357 AND `AIName` = '' AND `ScriptName` = '';
DELETE FROM `smart_scripts` WHERE `entryorguid` = 17357 AND `source_type` = 0;
